#include "netpulse/statistics.hpp"
#include <algorithm>
#include <fstream>
#include <iomanip>
#include <numeric>
namespace netpulse {
static double pct(const std::vector<double>&v,double p){if(v.empty())return 0;double ix=p*static_cast<double>(v.size()-1);auto lo=static_cast<std::size_t>(ix);auto hi=std::min(lo+1,v.size()-1);double f=ix-static_cast<double>(lo);return v[lo]*(1-f)+v[hi]*f;}
Metrics calculate(const Summary&s){Metrics m;if(!s.rtt_ms.empty()){auto v=s.rtt_ms;std::sort(v.begin(),v.end());m.min_ms=v.front();m.avg_ms=std::accumulate(v.begin(),v.end(),0.0)/static_cast<double>(v.size());m.median_ms=pct(v,.5);m.p95_ms=pct(v,.95);m.p99_ms=pct(v,.99);}if(s.duration_s>0){m.bytes_per_sec=s.bytes_received/s.duration_s;m.mib_per_sec=m.bytes_per_sec/(1024.0*1024.0);m.messages_per_sec=static_cast<double>(s.success)/s.duration_s;}return m;}
bool export_results(const Summary&s,const Metrics&m,const std::string&path,std::string&e){if(path.empty())return true;std::string csv=path, json=path;if(csv.size()<4||csv.substr(csv.size()-4)!=".csv")csv+=".csv";if(json.size()<5||json.substr(json.size()-5)!=".json")json+=".json";std::ofstream c(csv);if(!c){e="cannot open CSV output: "+csv;return false;}c<<"sent,received,success,errors,duration_s,bytes_sent,bytes_received,min_rtt_ms,avg_rtt_ms,median_rtt_ms,p95_rtt_ms,p99_rtt_ms,bytes_per_sec,mib_per_sec,messages_per_sec\n"<<s.sent<<','<<s.received<<','<<s.success<<','<<s.errors<<','<<std::setprecision(10)<<s.duration_s<<','<<s.bytes_sent<<','<<s.bytes_received<<','<<m.min_ms<<','<<m.avg_ms<<','<<m.median_ms<<','<<m.p95_ms<<','<<m.p99_ms<<','<<m.bytes_per_sec<<','<<m.mib_per_sec<<','<<m.messages_per_sec<<'\n';c.close();std::ofstream j(json);if(!j){e="cannot open JSON output: "+json;return false;}j<<std::setprecision(10)<<"{\n  \"sent\": "<<s.sent<<",\n  \"received\": "<<s.received<<",\n  \"success\": "<<s.success<<",\n  \"errors\": "<<s.errors<<",\n  \"duration_seconds\": "<<s.duration_s<<",\n  \"bytes_sent\": "<<s.bytes_sent<<",\n  \"bytes_received\": "<<s.bytes_received<<",\n  \"rtt_ms\": {\"min\": "<<m.min_ms<<", \"average\": "<<m.avg_ms<<", \"median\": "<<m.median_ms<<", \"p95\": "<<m.p95_ms<<", \"p99\": "<<m.p99_ms<<"},\n  \"throughput\": {\"bytes_per_second\": "<<m.bytes_per_sec<<", \"mib_per_second\": "<<m.mib_per_sec<<", \"messages_per_second\": "<<m.messages_per_sec<<"}\n}\n";return static_cast<bool>(j);}
}
